import { createSSRApp, h, useCssVars, renderSlot } from '@vue/runtime-dom'
test('repro', async () => {
  const Child = {
    props: { display: { default: 'flex' } },
    setup(props: any, { slots }: any) {
      return () =>
        h('div', { style: { display: props.display } }, renderSlot(slots, 'default'))
    },
  }
  const App = {
    setup() {
      useCssVars(() => ({ 'props\\.foo': 'red' }))
      return () =>
        h(Child, { class: 'p' }, { default: () => [h('div', { class: 'c' }, 'hi')] })
    },
  }
  const html = `<div style="display:flex;--props\\.foo:red;" class="p"><!--[--><div class="c">hi</div><!--]--></div>`
  const container = document.createElement('div')
  container.innerHTML = html
  createSSRApp(App).mount(container)
  expect(`Hydration style mismatch`).not.toHaveBeenWarned()
})
